const { DateTime } = require('luxon');

function nextMonthlyRun(schedule, after) {
  const zone = schedule.timezone || 'Asia/Kolkata';
  const [hour, minute, second = '0'] = String(schedule.time_of_day).split(':');
  const cursor = after.setZone(zone).startOf('month');

  for (let offset = 0; offset < 15; offset++) {
    const month = cursor.plus({ months: offset });
    const day = Math.min(Number(schedule.day_of_month), month.daysInMonth);
    const candidate = month.set({
      day,
      hour: Number(hour),
      minute: Number(minute),
      second: Number(second),
      millisecond: 0,
    });
    if (candidate.toMillis() > after.toMillis()) return candidate.toUTC().toISO();
  }
  throw new Error('Unable to calculate the next monthly run');
}

// HTTP Request may return a JSON array directly or as a body property.
// Empty claim results intentionally produce no output items.
const rows = items.flatMap(({ json }) => {
  const payload = json.body ?? json;
  if (Array.isArray(payload)) return payload;
  if (payload && payload.schedule_id) return [payload];
  return [];
});

const now = DateTime.now();
return rows.map(schedule => {
  if (!schedule.schedule_id || !schedule.time_of_day || !schedule.day_of_month) {
    throw new Error('Claimed schedule is missing required fields');
  }

  const next = nextMonthlyRun(schedule, now);
  if (!schedule.next_run_at) {
    return { json: { action: 'initialize', schedule_id: schedule.schedule_id, next_run_at: next } };
  }

  return {
    json: {
      action: 'enqueue',
      schedule_id: schedule.schedule_id,
      scheduled_for: schedule.next_run_at,
      next_run_at: next,
    },
  };
});
